<?php require __DIR__.'/../config.php';$id=(int)($_GET['id']??0);$mods=load_mods();$found=null;foreach($mods as &$m)if((int)$m['id']===$id){$found=$m;break;}unset($m);if(!$found){http_response_code(404);exit('Mod not found.');}$file=MOD_DIR.$found['filename'];if(!is_file($file)){http_response_code(404);exit('File is missing from storage.');}foreach($mods as &$m)if((int)$m['id']===$id){$m['downloads']=(int)($m['downloads']??0)+1;break;}unset($m);save_mods($mods);$name=preg_replace('/[^A-Za-z0-9._ -]/','_',$found['original_filename']);header('Content-Type:application/octet-stream');header('Content-Disposition:attachment; filename="'.$name.'"');header('Content-Length:'.filesize($file));header('X-Content-Type-Options:nosniff');$fp=fopen($file,'rb');while(!feof($fp)){echo fread($fp,1024*1024);flush();}fclose($fp);exit;